<script>
  /* ===== Live layer: refreshes pipeline stats from the viewer's Notion connector ===== */
  (async function () {
    var $ = function (id) { return document.getElementById(id); };
    var badge = $('live-badge'), badgeText = $('live-badge-text');
    function setBadge(cls, text) {
      if (!badge || !badgeText) return;
      badge.className = 'live-badge' + (cls ? ' ' + cls : '');
      badgeText.textContent = text;
    }

    var SNAP_TEXT = 'Snapshot · Aug 29 2026';
    var OPEN_STAGES = { 'Booked Call': 1, 'Showed': 1, 'Offer Made': 1 };
    var STAGES = ['Booked Call', 'Showed', 'Offer Made', 'Closed Won', 'No-Show', 'Nurture', 'Closed Lost', 'Unqualified'];

    // Snapshot values, restored if live access is revoked
    var SNAP = {
      total: 74, open: 49, askM: '$12.4M', stale: '41 of 49 open leads untouched 21+ days',
      stages: { 'Booked Call': 30, 'Showed': 11, 'Offer Made': 8, 'Closed Won': 6, 'No-Show': 12, 'Nurture': 3, 'Closed Lost': 2, 'Unqualified': 2 },
      attr: { v: 1, m: 2, u: 71 }, src: 'Meta Ad 66 · Other 4 · Referral 2 · Unknown 2'
    };

    function fmtMoney(n) {
      if (n >= 1e6) return '$' + (n / 1e6).toFixed(1).replace(/\.0$/, '') + 'M';
      if (n >= 1e3) return '$' + Math.round(n / 1e3) + 'K';
      return '$' + n;
    }

    function apply(stats) {
      var maxN = 1;
      STAGES.forEach(function (s) { maxN = Math.max(maxN, stats.stages[s] || 0); });
      document.querySelectorAll('#funnel .hbar-row').forEach(function (row) {
        var s = row.getAttribute('data-stage');
        var n = stats.stages[s] || 0;
        var bar = row.querySelector('.hbar'), num = row.querySelector('.num'), tip = row.querySelector('.tip');
        if (bar) bar.style.width = Math.max((n / maxN) * 100, n > 0 ? 2 : 0) + '%';
        if (num) num.textContent = n;
        if (tip && stats.total) tip.textContent = n + ' leads · ' + Math.round((n / stats.total) * 100) + '% of book';
      });
      if ($('lead-count')) $('lead-count').textContent = stats.total;
      if ($('tile-ask')) $('tile-ask').textContent = stats.askM;
      if ($('tile-open-n')) $('tile-open-n').textContent = stats.open;
      if ($('stale-line')) $('stale-line').textContent = stats.stale;
      var at = stats.attr.v + stats.attr.m + stats.attr.u || 1;
      if ($('attr-v')) $('attr-v').style.width = Math.max((stats.attr.v / at) * 100, stats.attr.v ? 1 : 0) + '%';
      if ($('attr-m')) $('attr-m').style.width = Math.max((stats.attr.m / at) * 100, stats.attr.m ? 1 : 0) + '%';
      if ($('attr-u')) $('attr-u').style.width = Math.max((stats.attr.u / at) * 100, stats.attr.u ? 1 : 0) + '%';
      if ($('attr-v-n')) $('attr-v-n').textContent = stats.attr.v;
      if ($('attr-m-n')) $('attr-m-n').textContent = stats.attr.m;
      if ($('attr-u-n')) $('attr-u-n').textContent = stats.attr.u;
      if ($('src-mix')) $('src-mix').textContent = stats.src;
    }

    function computeStats(rows) {
      var stages = {}, attr = { v: 0, m: 0, u: 0 }, src = {};
      var open = 0, ask = 0, stale = 0, total = rows.length;
      var cutoff = Date.now() - 21 * 86400000;
      rows.forEach(function (r) {
        var s = r['Stage'] || 'New Lead';
        stages[s] = (stages[s] || 0) + 1;
        var a = r['Attribution Confidence'];
        if (a && a.indexOf('Verified') === 0) attr.v++;
        else if (a === 'Missing') attr.m++;
        else attr.u++;
        var so = r['Source'] || 'Unknown';
        src[so] = (src[so] || 0) + 1;
        if (OPEN_STAGES[s]) {
          open++;
          if (typeof r['Funding Ask'] === 'number') ask += r['Funding Ask'];
          var lt = r['lt'];
          if (!lt || new Date(lt + 'T00:00:00').getTime() < cutoff) stale++;
        }
      });
      var srcTxt = Object.keys(src).sort(function (a, b) { return src[b] - src[a]; })
        .map(function (k) { return k + ' ' + src[k]; }).join(' · ');
      return {
        total: total, open: open, askM: fmtMoney(ask),
        stale: stale + ' of ' + open + ' open leads untouched 21+ days',
        stages: stages, attr: attr, src: srcTxt
      };
    }

    try {
      if (!window.claude || !window.claude.use) return; // saved copy — snapshot stands
      var mcp = await window.claude.use('mcp');
      if (!mcp) return; // capability unavailable on this view — snapshot stands

      var DS = 'collection://5614ffa0-e3d0-40cb-ae64-b32ec52e288c';
      var input = { data: { data_source_urls: [DS], query:
        'SELECT "Stage", "Attribution Confidence", "Source", "Funding Ask", "date:Last Touch:start" AS lt FROM "' + DS + '"' } };
      var applied = false;

      mcp.watchTool('Notion', 'notion-query-data-sources', input, function (ev) {
        if (ev.type === 'data') {
          var p = ev.result && ev.result.payload;
          if (typeof p === 'string') { try { p = JSON.parse(p); } catch (e) { p = null; } }
          var rows = p && p.results;
          if (!Array.isArray(rows) || rows.length === 0) {
            setBadge('err', 'Live feed: unexpected data — snapshot shown');
            return;
          }
          apply(computeStats(rows));
          applied = true;
          var ts = (ev.result.cache && ev.result.cache.storedAt) ? new Date(ev.result.cache.storedAt) : new Date();
          setBadge('live', 'Live · Notion · ' + ts.toLocaleTimeString([], { hour: 'numeric', minute: '2-digit' }));
        } else if (ev.type === 'error') {
          var c = ev.error && ev.error.code;
          if (c === 'needs_reauth') { if (applied) { apply(SNAP); applied = false; } setBadge('err', 'Reconnect Notion in claude.ai Settings → Connectors'); }
          else if (c === 'server_not_connected') { if (applied) { apply(SNAP); applied = false; } setBadge('', SNAP_TEXT + ' — add Notion in Settings → Connectors for live data'); }
          else if (c === 'blocked_by_policy' || c === 'approval_required' || c === 'not_granted') { if (applied) { apply(SNAP); applied = false; } setBadge('', SNAP_TEXT); }
          else if (c === 'tool_error') { setBadge('err', applied ? 'Live paused — query failed; last data shown' : 'Live query failed — snapshot shown'); }
          else if (c === 'selection_required') { setBadge('', SNAP_TEXT + ' — choose a Notion connector when prompted'); }
          else { setBadge(applied ? 'live' : '', applied ? badgeText.textContent : SNAP_TEXT); }
        }
      }, { refetchInterval: 300000, cache: { staleTime: 60000 } });
    } catch (e) { setBadge('', SNAP_TEXT); }
  })();
</script>

